import sys

COMMON = {"passwordpassword", "123456789012345", "qwertyuiopasdfgh",
          "iloveyouiloveyou", "correcthorsebatterystaple"}

lines = sys.stdin.read().split('\n')
password = lines[0].rstrip('\r')
username = lines[1].strip() if len(lines) > 1 else ''

problems = []
if len(password) < 15:
    problems.append('too short (minimum 15 characters)')
if len(password) > 64:
    problems.append('too long (maximum 64 characters)')
if password.lower() in COMMON:
    problems.append('too common')
if username and username.lower() in password.lower():
    problems.append('contains the username')
if password and len(set(password)) == 1:
    problems.append('one repeated character')

print('\n'.join(problems) if problems else 'OK')

