import sys, json, base64, hmac, hashlib

token, secret, now = sys.stdin.read().split('\n')[:3]
now = int(now)
h64, p64, s64 = token.strip().split('.')

def decode(part):
    part += '=' * (-len(part) % 4)
    return json.loads(base64.urlsafe_b64decode(part))

header = decode(h64)
payload = decode(p64)
alg = header.get('alg')
print('alg: ' + str(alg))

if alg == 'HS256':
    mac = hmac.new(secret.strip().encode(), (h64 + '.' + p64).encode(), hashlib.sha256).digest()
    expected = base64.urlsafe_b64encode(mac).rstrip(b'=').decode()
    print('signature: ' + ('valid' if hmac.compare_digest(expected, s64) else 'invalid'))
else:
    print('signature: rejected (alg ' + str(alg) + ')')

if 'exp' not in payload:
    print('status: no expiry')
elif payload['exp'] <= now:
    print('status: expired')
else:
    print('status: active')

for key in sorted(payload):
    value = payload[key]
    print(key + ' = ' + (value if isinstance(value, str) else json.dumps(value)))

