exercise.solution:
import sys

section = None
roles = {}
users = {}
for raw in sys.stdin.read().split('\n'):
    line = raw.strip()
    if not line:
        continue
    if line in ('roles', 'users', 'checks'):
        section = line
        continue
    if section == 'roles':
        name, _, rest = line.partition(':')
        roles[name.strip()] = {p.strip() for p in rest.split(',') if p.strip()}
    elif section == 'users':
        name, _, rest = line.partition(':')
        users[name.strip()] = [r.strip() for r in rest.split(',') if r.strip()]
    elif section == 'checks':
        user, perm = line.split()
        allowed = any(perm in roles.get(r, set()) for r in users.get(user, []))
        print(('ALLOW ' if allowed else 'DENY ') + user + ' ' + perm)
